"""Embed src/ui/index.html into src/ui_html.h, so the canister can serve it.

Run from the project root after editing the page:  python3 -I scripts/embed_ui.py
"""

import pathlib

ROOT = pathlib.Path(__file__).resolve().parent.parent
html = (ROOT / "src/ui/index.html").read_text(encoding="utf-8")
assert ')HTML"' not in html, "the page must not contain the raw-string delimiter"

(ROOT / "src/ui_html.h").write_text(
    "// Generated by scripts/embed_ui.py from src/ui/index.html. Do not edit.\n"
    "#pragma once\n\n"
    f'static const char UI_HTML[] = R"HTML({html})HTML";\n',
    encoding="utf-8",
)
print(f"src/ui_html.h: {len(html.encode())} bytes of HTML")
